sys_script_include.script:
var CouseScheduleAjaxUtils = Class.create();
CouseScheduleAjaxUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

		getEncodedQuery: function(){
		var encodedQuery = this.getParameter("sysparm_encoded_query");
		var results = [];
		gs.info("script está sendo triggado?", "ilwel debug");
		gs.info(encodedQuery, "ilwel debug");
		if(encodedQuery){
			var gr = new GlideRecord("x_1593190_course_0_course_schedule");
			gr.addEncodedQuery(encodedQuery);
			gr.query();
			while(gr.next()){
				gs.info("trouxe resultados");
				gs.info(gr.course.name, "ilwel debug");
				results.push({
					sys_id: gr.sys_id.toString(),
					course: gr.course.name.toString()
				});
			}
			return JSON.stringify(results);
		}
		return "something";
	},

    type: 'CouseScheduleAjaxUtils'
});
